import { renderDashboard, icon } from './dashboard.js?v=ux22';
import {localDate,scheduleReview} from './reviews.js';
import { errorState, emptyState, loadingState } from './ui.js';
import{authored,key,parseOptions,fingerprint,canGrade,grade,importItems,shuffle}from'./core.js?v=ux22';
import{newCode,normalizeCode,hashCode,mergeProgress,createSync,sanitizeProgress}from'./sync.js?v=ux22';import{SYNC}from'./sync-config.js?v=ux22';import qrcode from'./qr.js?v=ux22';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kinds={FISZKA:'Fiszka',ODPOWIEDZ_OTWARTA:'Otwarte',ABCDE:'ABCDE',DO_POPRAWY:'Do poprawy'};let db=[],progress={},approved=new Map(),session=null,filters={q:'',topic:'',kind:'',status:'',origin:'',year:'',round:'',sort:'id'},motion=true,baseCount=0;
function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}function save(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('Brak dostępu do zapisu. Dane pozostają tylko w tej sesji.');return false}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',5500)}
const reviewed=i=>approved.get(key(i))===fingerprint(i);function label(i){return authored(i)?'Autorskie EBM':/odczyt|powtórkowe|rubryka|aktualizacja/.test(i.provenance||'')?'Opracowane z giełdy':'Materiał z giełdy'}function badges(i){return `<span class="badge">${esc(kinds[i.kind]||'Archiwum')}</span><span class="badge">${label(i)}</span>${verifyBadge(i)}`}
function metadata(i){return `<details><summary>Źródła, pochodzenie i weryfikacja</summary><dl>${[['ID',i.id],['Pochodzenie',i.provenance],['Status w pliku',i.verification_status],['Plik / lokalizacja',`${i.source||'—'} · ${i.location||'—'}`],['Grupa powtórzeń',i.duplicate||'Nie podano'],['Oryginalna treść',i.original_question||'Nie wydzielono w pliku. Treść pytania pochodzi z importu.'],['Odpowiedź studenta',i.original_answer||i.student_answer||'Nie dostarczono'],['Data źródła',i.source_date||'Nie podano w pliku'],['Sprawdzenie klucza',reviewed(i)?'2026-11-11 · zgodność z treścią CDC; nie recenzja kliniczna':'Nie przeprowadzono w tej aplikacji']].map(([a,b])=>`<dt>${esc(a)}</dt><dd>${esc(b||'—')}</dd>`).join('')}<dt>Źródło odpowiedzi</dt><dd>${/^https?:\/\//.test(i.reference||'')?`<a target="_blank" rel="noopener noreferrer" href="${esc(i.reference)}">Otwórz źródło ↗</a>`:esc(i.reference||'Nie podano')}</dd></dl></details>`}
function stats(){const p=Object.values(progress),a=p.reduce((s,x)=>s+(x.attempts||0),0),c=p.reduce((s,x)=>s+(x.correct||0),0);return{done:p.filter(x=>x.seen).length,due:db.filter(i=>i.kind!=='DO_POPRAWY'&&progress[key(i)]?.due<=Date.now()),accuracy:a?Math.round(c/a*100)+'%':'—',attempts:a}}function statsHTML(){let s=stats();return `<div class="stats">${[[db.length,'pozycji w bibliotece'],[s.done,'przerobionych pozycji'],[s.due.length,'powtórek na teraz'],[s.accuracy,'trafność ocenianych quizów']].map(([n,t])=>`<div class="stat"><strong>${n}</strong><span>${t}</span></div>`).join('')}</div>`}function heading(t,d){return `<div class="topline"><div><div class="eyebrow">TWOJA NAUKA, TWÓJ RYTM</div><h1>${t}</h1><p>${d}</p></div><span class="tag">Baza v7</span></div>`}
function home(){return renderDashboard(db,progress,stats())}
function options(values,selected,all){return `<option value="">${all}</option>`+values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('')}
function library(){const unique=f=>[...new Set(db.map(i=>i[f]).filter(Boolean))].sort();return heading('Biblioteka pytań','Twoje materiały, źródła i statusy — w jednym miejscu.')+`<div class="actions"><button class="primary" id="import-btn">Importuj JSON</button><button id="export-db">Eksportuj bazę</button></div><div class="toolbar"><input aria-label="Szukaj pytań" type="search" id="search" placeholder="Szukaj pytania, odpowiedzi lub ID…" value="${esc(filters.q)}">${[['topic','Temat','Wszystkie tematy'],['kind','Typ','Wszystkie typy'],['status','Status','Wszystkie statusy'],['origin','Pochodzenie','Każde pochodzenie'],['year','Rok','Każdy rok (jeśli podany)'],['round','Tura','Każda tura (jeśli podana)'],['sort','Sortowanie','Kolejność importu']].map(([f,label,all])=>`<select aria-label="${label}" data-filter="${f}">${options(f==='origin'?['Autorskie EBM','Materiały z giełdy']:f==='sort'?['id','topic','question']:unique(f==='status'?'verification_status':f).map(String),filters[f],all)}</select>`).join('')}<button id="clear-filters">Wyczyść</button></div><div id="results"></div>`}
function results(){let list=db.filter(i=>(!filters.q||`${i.question} ${i.answer} ${i.id}`.toLocaleLowerCase('pl').includes(filters.q.toLocaleLowerCase('pl')))&&(!filters.topic||i.topic===filters.topic)&&(!filters.kind||i.kind===filters.kind)&&(!filters.status||i.verification_status===filters.status)&&(!filters.origin||(filters.origin==='Autorskie EBM')===authored(i))&&(!filters.year||String(i.year)===filters.year)&&(!filters.round||String(i.round)===filters.round));if(filters.sort)list.sort((a,b)=>String(a[filters.sort]||'').localeCompare(String(b[filters.sort]||''),'pl'));$('#results').innerHTML=`<p>${list.length} z ${db.length} pozycji · ${db.filter(authored).length} autorskich EBM</p>`+list.map(i=>`<article class="item"><div>${badges(i)}<h3>${esc(qText(i)||'Niekompletny rekord — brak treści pytania')}</h3><small>${esc(i.id)} · ${esc(i.topic||'Bez tematu')}${i.duplicate?' · grupa '+esc(i.duplicate):''}</small></div><button data-detail="${esc(key(i))}">Zobacz</button></article>`).join('')+(list.length?'':emptyState('Brak pasujących pytań', 'Zmień filtry lub wróć do pełnej biblioteki.', 'Wyczyść filtry', 'clear-filters'))}
function start(mode){let pool;if(mode==='mix')pool=shuffle(db.filter(i=>i.kind!=='DO_POPRAWY'&&i.question&&i.answer)).slice(0,20);else{pool=mode==='review'?stats().due:db.filter(i=>i.kind===mode&&i.question&&i.answer&&(mode!=='ABCDE'||canGrade(i,approved)));if(shuffleOn()&&mode!=='review')pool=shuffle(pool)}session={mode,pool,perm:{},index:0,revealed:false,choice:null,recorded:false,draft:''};if(location.hash==='#study')render();else location.hash='study'}
function study(){if(!session)return heading('Wybierz sposób nauki','Zacznij od fiszek, pytań otwartych lub quizu.')+`<button data-start="${['FISZKA','ODPOWIEDZ_OTWARTA','ABCDE'].find(k=>db.some(i=>i.kind===k))||'ABCDE'}" class="primary">Zacznij naukę</button>`;let s=session,i=s.pool[s.index];persistSession(s,i);if(!i)return `<div class="empty"><span class="icon">✓</span><h1>${s.pool.length?(s.pool.length===1?'Pytanie przerobione.':'Przerobione: '+s.pool.length+' z '+s.pool.length+'.'):'Na teraz wszystko gotowe.'}</h1><p>${s.pool.length?'Postęp został zapisany w tej przeglądarce.':'Brak pozycji w tej kolejce. Wybierz inny tryb nauki.'}</p><div class="actions" style="justify-content:center">${s.pool.length&&s.mode!=='review'?`<button class="primary" data-start="${esc(s.mode)}">Ucz się dalej</button>`:''}<a href="#home" class="end-link">Wróć do pulpitu</a></div></div>`;const quiz=i.kind==='ABCDE'&&canGrade(i,approved);return `<div class="study"><div class="topline"><a href="#home">← Pulpit</a><span>${s.index+1} / ${s.pool.length} · ${esc(kinds[i.kind]||'Powtórka')}</span></div><div class="progress"><span style="width:${s.index/s.pool.length*100}%"></span></div><section class="card"><div>${badges(i)}</div><p>${esc(i.topic)}</p><h1 class="question">${esc(qText(i))}</h1>${i.kind==='ODPOWIEDZ_OTWARTA'?`<label for="draft">Twoja odpowiedź</label><textarea id="draft" placeholder="Zapisz to, co pamiętasz…">${esc(s.draft)}</textarea><small class="muted">Oceniasz się samodzielnie na podstawie kryteriów.</small>`:''}${quiz?optionOrder(s,i).map((o,n)=>`<button class="option ${s.choice?(o.letter===i.correct_option?'correct':o.letter===s.choice?'wrong':''):''}" data-choice="${o.letter}" ${s.choice?'disabled':''}><b>${'ABCDE'[n]}</b><span>${esc(o.text)}</span></button>`).join(''):''}${s.revealed?`<div class="answer"><strong>${quiz?(s.choice===i.correct_option?'Dobra odpowiedź.':'Wróć do tego pytania.'):'Odpowiedź z materiału'}</strong>${quiz&&i.verified_by?quizAnswer(i,'ABCDE'[optionOrder(s,i).findIndex(o=>o.letter===i.correct_option)]):`<p>${esc(i.answer||'Brak odpowiedzi')}</p>`}${i.explanation?`<p>${esc(i.explanation)}</p>`:''}${i.criteria?`<strong>Kryteria odpowiedzi</strong><p>${esc(i.criteria)}</p>`:''}</div>${quiz?'<div class="actions"><button class="primary" id="next">Następne pytanie</button></div>':`<div class="actions"><button data-rate="again">Jeszcze powtórzę</button><button data-rate="good" class="primary">Pamiętam</button></div>`}`:!quiz?'<button class="primary" id="reveal">Odkryj odpowiedź</button>':''}<div class="review-action"><button data-plan="${esc(key(i))}">${icon('calendar')}Zaplanuj powtórkę</button><span>${progress[key(i)]?.due?'Termin: '+new Date(progress[key(i)].due).toLocaleDateString('pl-PL'):'Wybierz własny termin powrotu do tego pytania.'}</span></div>${metadata(i)}</section></div>`}
function record(result,isQuiz){const i=session.pool[session.index],k=key(i),p=progress[k]||{seen:false,attempts:0,correct:0};p.seen=true;p.last=Date.now();p.due=p.due>Date.now()?p.due:Date.now()+(result?3*86400000:600000);p.lastResult=result;if(isQuiz){p.attempts++;p.correct+=Number(result)}progress[k]=p;save('infectio-progress',progress);queueSync()}
function progressPage(){const s=stats();return heading('Twój postęp','Prawdziwe wyniki. Własne tempo.')+statsHTML()+reviewPlan()+`<button class="primary" data-start="review">Rozpocznij powtórki</button> <button id="backup">Pobierz kopię postępu</button> <button id="restore">Wczytaj kopię postępu</button><input type="file" id="restore-file" accept=".json,application/json" hidden>${syncCard()}<div class="two"><section class="card"><h2>Tematy do powtórzenia</h2>${[...new Set(db.filter(i=>progress[key(i)]?.lastResult===false).map(i=>i.topic))].map(t=>`<div class="topic-row">${esc(t)}</div>`).join('')||'<p>Po pierwszych odpowiedziach zobaczysz tutaj tematy wymagające powtórki.</p>'}</section><section class="card"><h2>Jak liczymy postęp?</h2><p>Fiszki i pytania otwarte zapisują samoocenę. Trafność obejmuje tylko ocenione odpowiedzi ABCDE (${s.attempts} prób).</p><p>Bez własnego terminu „Jeszcze powtórzę” wraca po 10 minutach, a „Pamiętam” po 3 dniach. Przyszły termin ustawiony ręcznie zostaje zachowany. ${syncState?'Wyniki zapisują się na tym urządzeniu i w synchronizacji kodem.':'Dane są lokalne dla tej przeglądarki.'}</p></section></div>`}
function exam(){return heading('Tryb egzaminu','Najpierw wiarygodna baza, potem pełna symulacja.')+`<div class="card"><span class="badge warn">Zestaw niekompletny</span><h2>Pełny egzamin nie jest jeszcze dostępny.</h2><p>Dostępnych jest ${db.filter(i=>canGrade(i,approved)).length} pytań ze sprawdzonym kluczem. Ta pula nie zapewnia reprezentatywnego pokrycia tematów egzaminacyjnych.</p><button class="primary" data-start="ABCDE">Ćwicz w quizie ABCDE</button></div>`}
const nav=[['home','◫','Pulpit'],['library','▤','Biblioteka'],['flash','▱','Fiszki'],['open','✎','Pytania otwarte'],['quiz','☷','Quiz ABCDE'],['exam','◷','Egzamin'],['progress','↗','Mój postęp']];const observer=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('away',!e.isIntersecting)),{threshold:.05});
function render(){let route=location.hash.slice(1)||'home';if(['flash','open','quiz'].includes(route)){start({flash:'FISZKA',open:'ODPOWIEDZ_OTWARTA',quiz:'ABCDE'}[route]);return}const activeRoute=route==='study'?({FISZKA:'flash',ODPOWIEDZ_OTWARTA:'open',ABCDE:'quiz',mix:'quiz',review:'progress'}[session?.mode]||'flash'):route;$('#nav').innerHTML=nav.filter(([id])=>{const k={flash:'FISZKA',open:'ODPOWIEDZ_OTWARTA'}[id];return!k||db.some(i=>i.kind===k)}).map(([id,ic,t])=>`<a href="#${id}" class="${activeRoute===id?'active':''}" ${activeRoute===id?'aria-current="page"':''}>${icon({home:'grid',library:'book',flash:'cards',open:'note',quiz:'check',exam:'clock',progress:'chart'}[id])}<span>${t}</span></a>`).join('');$('#app').innerHTML=route==='library'?library():route==='study'?study():route==='progress'?progressPage():route==='exam'?exam():home();document.body.classList.toggle('dashboard-view',route==='home');if(route==='library')results();observer.disconnect();document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-plan'))openPlanner(b.dataset.plan,b.dataset.planDate);if(b.dataset.cancelReview){const k=b.dataset.cancelReview;const updated={...progress,[k]:{...progress[k]}};delete updated[k].due;if(save('infectio-progress',updated)){progress=updated;render();toast('Usunięto termin powtórki.')}}if(b.dataset.learn){const item=db.find(i=>key(i)===b.dataset.learn);if(item){session={mode:item.kind,pool:[item],perm:{},index:0,revealed:false,choice:null,recorded:false,draft:''};location.hash==='#study'?render():location.hash='study'}}if(b.dataset.start)start(b.dataset.start);if(b.dataset.topic){filters.topic=b.dataset.topic;location.hash='library'}if(b.dataset.detail){const i=db.find(i=>key(i)===b.dataset.detail);$('#detail-body').innerHTML=`${badges(i)}${i.fix_note?`<p class="notice">Wymaga poprawy: ${esc(i.fix_note)}</p>`:''}<h2>${esc(qText(i)||'Brak treści')}</h2><p>${esc(i.options)}</p><div class="answer">${esc(i.answer||'Brak odpowiedzi w źródle')}</div>${i.criteria?`<h3>Kryteria</h3><p>${esc(i.criteria)}</p>`:''}${metadata(i)}<div class="actions"><button data-plan="${esc(key(i))}">${icon('calendar')}Zaplanuj powtórkę</button></div>`;$('#detail').showModal()}if(b.id==='close')$('#detail').close();if(b.id==='reveal'){session.revealed=true;render()}if(b.dataset.choice&&!session.recorded){const i=session.pool[session.index];try{const correct=grade(i,b.dataset.choice,approved);session.choice=b.dataset.choice;session.revealed=true;session.recorded=true;record(correct,true);render()}catch(err){toast(err.message)}}if(b.dataset.rate){record(b.dataset.rate==='good',false);next()}if(b.id==='next')next();if(b.id==='import-btn')$('#import').click();if(b.id==='export-db')download('infectio-baza.json',{schema_version:'infectio.study.v4',items:db});if(b.id==='backup')download('infectio-postep.json',progress);if(b.id==='clear-filters'){Object.keys(filters).forEach(k=>filters[k]=k==='sort'?'id':'');render()}if(b.id==='motion'){motion=!motion;save('infectio-motion',motion);applyMotion()}});
function next(){session.index++;session.revealed=false;session.choice=null;session.recorded=false;session.draft='';render()}document.addEventListener('input',e=>{if(e.target.id==='search'){filters.q=e.target.value;results()}if(e.target.id==='draft')session.draft=e.target.value});document.addEventListener('change',e=>{if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;results()}});
$('#import').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Maksymalny rozmiar to 20 MB.');const parsed=JSON.parse(await file.text()),merged=importItems(parsed,db),n=merged.length-db.length;if(!save('infectio-imports',merged.slice(baseCount)))return;db=merged;render();toast(`Dodano ${n} rekordów. Importowane klucze wymagają oddzielnej weryfikacji.`)}catch(err){toast(err.message)}finally{e.target.value=''}});
function applyMotion(){document.body.classList.toggle('no-motion',!motion);}async function init(){$('#app').innerHTML=loadingState();try{const res=await fetch(new URL('data.json?v=v8',import.meta.url));if(!res.ok)throw Error('Nie udało się wczytać danych');db=importItems(await res.json());baseCount=db.length;for(const i of db){const n=Number(i.id.replace('EBM',''));if(authored(i)&&((n>=1&&n<=13)||n===17||n===18))approved.set(key(i),fingerprint(i))}const extra=read('infectio-imports',[]);if(extra.length){try{db=importItems(extra,db)}catch{toast('Nie wczytano uszkodzonego lokalnego importu.')}}try{const vr=await fetch(new URL('verification.json?v=v8',import.meta.url));if(vr.ok)applyVerification(await vr.json())}catch{}progress=read('infectio-progress',{});motion=true;applyMotion();const jm=location.hash.match(/^#sync=([A-Za-z0-9 -]+)/i);if(jm){pendingJoin=jm[1];history.replaceState(null,'',location.pathname+location.search+'#progress')}render();if(pendingJoin!==null)offerJoin();else syncNow(true)}catch(err){$('#app').innerHTML=errorState(err.message);$('#retry-load').addEventListener('click',init)}}window.addEventListener('hashchange',()=>{const paint=()=>{render();window.scrollTo(0,0)};if(document.startViewTransition&&motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches)document.startViewTransition(paint);else paint()});document.querySelector('#global-search').addEventListener('submit',e=>{e.preventDefault();filters.q=document.querySelector('#global-query').value;location.hash==='#library'?render():location.hash='library'});init();

function reviewPlan(){const planned=db.filter(i=>progress[key(i)]?.due).sort((a,b)=>progress[key(a)].due-progress[key(b)].due);return `<section class="card review-plan"><div class="plan-heading"><h2>Plan powtórek</h2><button class="primary" data-plan="">${icon('calendar')}Zaplanuj powtórkę</button></div>${planned.length?planned.map(i=>`<div class="plan-row"><div><strong>${esc(qText(i))}</strong><small>${new Date(progress[key(i)].due).toLocaleDateString('pl-PL')}${progress[key(i)].due<=Date.now()?' · Do powtórki':''}</small></div><div class="actions"><button data-learn="${esc(key(i))}">Ucz się</button><button data-plan="${esc(key(i))}">Zmień termin</button><button data-cancel-review="${esc(key(i))}" aria-label="Usuń termin: ${esc(qText(i))}">Usuń termin</button></div></div>`).join(''):'<p>Nie masz jeszcze zaplanowanych powtórek. Wybierz pytanie i dzień, w którym chcesz do niego wrócić.</p>'}</section>`}
function openPlanner(itemKey='',date=''){if($('#detail').open)$('#detail').close();let dialog=$('#review-planner');if(!dialog){dialog=document.createElement('dialog');dialog.id='review-planner';dialog.setAttribute('aria-labelledby','review-title');document.body.append(dialog)}const item=db.find(i=>key(i)===itemKey);const selected=date|| (item&&progress[itemKey]?.due?localDate(new Date(progress[itemKey].due)):localDate());dialog.innerHTML=`<form id="review-form"><h2 id="review-title">Zaplanuj powtórkę</h2><p>Wybierz pytanie i dzień. Termin zobaczysz w kalendarzu oraz w planie powtórek.</p><label for="review-search">Znajdź pytanie</label><input id="review-search" type="search" placeholder="Wpisz temat, treść lub ID"><label for="review-item">Pytanie</label><select id="review-item" required>${db.filter(i=>i.question&&i.answer).map(i=>`<option value="${esc(key(i))}" ${key(i)===itemKey?'selected':''}>${esc(i.id+' · '+i.question)}</option>`).join('')}</select><label for="review-date">Termin powtórki</label><input id="review-date" type="date" required min="${localDate()}" value="${selected<localDate()?localDate():selected}"><p id="review-error" role="alert"></p><div class="actions"><button type="submit" class="primary">${icon('calendar')}Zapisz termin</button><button type="button" id="cancel-planner">Anuluj</button></div><small>Zapis na tym urządzeniu. Aplikacja nie wysyła powiadomień.</small></form>`;dialog.querySelector('#review-search').oninput=e=>{const q=e.target.value.toLocaleLowerCase('pl');const items=db.filter(i=>i.question&&i.answer&&`${i.id} ${i.topic} ${i.question}`.toLocaleLowerCase('pl').includes(q));$('#review-item').innerHTML=items.map(i=>`<option value="${esc(key(i))}">${esc(i.id+' · '+i.question)}</option>`).join('');$('#review-error').textContent=items.length?'':'Brak pasujących pytań. Zmień wyszukiwanie.'};dialog.querySelector('#cancel-planner').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();try{const updated=scheduleReview(progress,$('#review-item').value,$('#review-date').value);if(!save('infectio-progress',updated))throw Error('Nie udało się zapisać terminu.');progress=updated;dialog.close();render();toast('Zapisano termin powtórki.')}catch(err){$('#review-error').textContent=err.message}};dialog.showModal()}

/* ---- synchronizacja kodem ---- */
const sync=createSync(SYNC);let syncState=read('infectio-sync',null),syncTimer=0,syncBusy=false,syncError=false;
function syncCard(){if(!sync.enabled)return'';const when=syncState?.at?new Date(syncState.at).toLocaleString('pl',{dateStyle:'short',timeStyle:'short'}):'jeszcze nie';return`<section class="card sync-card" id="sync-card"><h2>Synchronizacja między urządzeniami</h2>${syncState?`<p>Wpisz ten kod na drugim urządzeniu, a zobaczysz tam te same wyniki. Traktuj go jak hasło.</p><p class="sync-code" aria-label="Twój kod synchronizacji">${esc(syncState.code)}</p><div class="sync-qr" role="img" aria-label="Kod QR do połączenia drugiego urządzenia">${qrSvg(syncLink())}</div><p class="sync-hint">Zeskanuj aparatem telefonu, aby połączyć go z tymi wynikami. Nic nie musisz przepisywać.</p><p class="sync-status" role="status">${syncError?'Nie udało się połączyć. Postęp zostaje na tym urządzeniu i zsynchronizuje się później.':'Ostatnia synchronizacja: '+esc(when)+'.'}</p><div class="actions"><button id="sync-now" class="primary">Synchronizuj teraz</button><button id="sync-link">Skopiuj link</button><button id="sync-copy">Skopiuj kod</button><button id="sync-off">Wyłącz na tym urządzeniu</button></div><small>Na serwerze zapisują się tylko wyniki nauki. Bez pytań, notatek i e-maila. Po wyłączeniu kopia na serwerze zostaje, a kod nadal ją otwiera.</small>`:`<p>Zapisuj wyniki poza przeglądarką i miej je na telefonie i komputerze. Bez konta i bez e-maila: dostajesz kod.</p><div class="actions"><button id="sync-on" class="primary">Włącz synchronizację</button></div><label for="sync-code">Mam już kod z innego urządzenia</label><div class="actions"><input id="sync-code" autocomplete="off" autocapitalize="characters" placeholder="XXXXX-XXXXX-XXXXX-XXXXX"><button id="sync-join">Połącz</button></div>`}</section>`}
async function syncNow(quiet){if(!sync.enabled||!syncState||syncBusy)return;syncBusy=true;try{const id=await hashCode(syncState.code);const remote=await sync.pull(id);progress=mergeProgress(progress,remote||{});save('infectio-progress',progress);await sync.push(id,progress);syncState={...syncState,at:Date.now()};save('infectio-sync',syncState);syncError=false}catch{syncError=true;if(!quiet)toast('Nie udało się zsynchronizować. Spróbuj ponownie za chwilę.')}finally{syncBusy=false;if(['#progress','#home',''].includes(location.hash))render()}}
function queueSync(){if(!sync.enabled||!syncState)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncNow(true),2500)}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||!b.id?.startsWith('sync-'))return;
if(b.id==='sync-on'){syncState={code:newCode(),at:0};save('infectio-sync',syncState);await syncNow();toast('Synchronizacja włączona. Zapisz swój kod.')}
if(b.id==='sync-join'){const code=normalizeCode(document.querySelector('#sync-code')?.value);if(!code){toast('Kod ma 20 znaków, np. ABCDE-FGHJK-LMNPQ-RSTUV.');return}syncState={code,at:0};save('infectio-sync',syncState);await syncNow();if(!syncError)toast('Połączono. Wyniki z obu urządzeń zostały scalone.');else{syncState=null;save('infectio-sync',null);render()}}
if(b.id==='sync-now')await syncNow();
if(b.id==='sync-copy'){try{await navigator.clipboard.writeText(syncState.code);toast('Skopiowano kod.')}catch{toast('Nie udało się skopiować. Zaznacz kod i skopiuj ręcznie.')}}
if(b.id==='sync-link'){try{await navigator.clipboard.writeText(syncLink());toast('Skopiowano link. Otwórz go na drugim urządzeniu.')}catch{toast('Nie udało się skopiować linku.')}}
if(b.id==='sync-off'){syncState=null;save('infectio-sync',null);render();toast('Synchronizacja wyłączona na tym urządzeniu.')}});

/* ---- wznawianie sesji i wczytywanie kopii ---- */
function persistSession(s,i){save('infectio-session',i?{mode:s.mode,keys:s.pool.map(key),index:s.index}:null)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.dataset.resume!==undefined){const r=read('infectio-session',null);const pool=(r?.keys||[]).map(k=>db.find(i=>key(i)===k)).filter(Boolean);if(!pool.length){save('infectio-session',null);render();return}session={mode:r.mode,pool,perm:{},index:Math.min(r.index,pool.length-1),revealed:false,choice:null,recorded:false,draft:''};location.hash==='#study'?render():location.hash='study'}
if(b.id==='restore')document.querySelector('#restore-file')?.click()});
document.addEventListener('change',async e=>{if(e.target.id!=='restore-file')return;try{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024)throw Error('Plik jest zbyt duży.');const clean=sanitizeProgress(JSON.parse(await f.text()));progress=mergeProgress(progress,clean);if(!save('infectio-progress',progress))return;queueSync();render();toast('Wczytano kopię: '+Object.keys(clean).length+' pozycji scalono z Twoim postępem.')}catch(err){toast(err instanceof SyntaxError?'Plik nie jest poprawnym JSON.':err.message)}e.target.value=''});

/* ---- łączenie przez QR / link ---- */
let pendingJoin=null;
function syncLink(){return location.origin+location.pathname+'#sync='+syncState.code}
function qrSvg(text){try{const q=qrcode(0,'M');q.addData(text);q.make();return q.createSvgTag(4,2)}catch{return''}}
async function offerJoin(){const raw=pendingJoin;pendingJoin=null;if(!sync.enabled)return;const code=normalizeCode(raw);if(!code){toast('Ten link do synchronizacji jest niepoprawny.');return}if(syncState?.code===code){syncNow(true);return}
const ok=confirm('Połączyć to urządzenie z synchronizacją?\n\nWyniki z tego urządzenia zostaną scalone z wynikami zapisanymi pod tym kodem'+(syncState?' i zastąpią dotychczasowe połączenie.':'.')+'\nRób to tylko z linku lub kodu QR, który wygenerowałeś sam.');if(!ok){syncNow(true);return}
const prev=syncState;syncState={code,at:0};save('infectio-sync',syncState);await syncNow();if(syncError){syncState=prev;save('infectio-sync',syncState);render()}else toast('Połączono. Wyniki z obu urządzeń zostały scalone.')}

/* ---- weryfikacja kluczy i quiz A–E ---- */
const qText=i=>String(i.question||'').split(/\n\nWybierz odpowiedź/)[0];
function applyVerification(v){const ok=new Set(v.reviewed||[]),easy=new Set(v.easy||[]),rew=new Set(v.rewritten||[]);for(const i of db){if(!ok.has(i.id))continue;const f=v.flags?.[i.id];if(!/^[A-E]$/.test(i.answer_key||'')||parseOptions(i).length!==5)continue;if(f?.level==='blad'){i.kind='DO_POPRAWY';i.fix_note=f.note;continue}i.kind='ABCDE';i.correct_option=i.answer_key;i.verified_by=v.checked_by;i.verify_date=v.date;if(f)i.verify_note=f.note;if(easy.has(i.id))i.easy=true;if(rew.has(i.id))i.rewritten=true;approved.set(key(i),fingerprint(i))}}
function quizAnswer(i,shown){const o=parseOptions(i).find(x=>x.letter===i.correct_option);return`<p>Poprawna odpowiedź: <b>${esc(shown||i.correct_option)}</b>) ${esc(o?.text||'')}</p><p class="muted">Klucz sprawdzony ${esc(i.verify_date)} przez ${esc(i.verified_by)}. To nie jest recenzja kliniczna.${i.verify_note?' '+esc(i.verify_note):''}${i.rewritten?' Błędne warianty napisał Claude i nie przeszły recenzji klinicznej.':i.easy?' Błędne warianty są ogólnikowe, więc wynik może zawyżać wiedzę.':''}</p>`}
function verifyBadge(i){if(i.kind==='DO_POPRAWY')return'<span class="badge warn">Wymaga poprawy</span>';if(i.verified_by)return`<span class="badge ${i.verify_note?'warn':''}">Klucz sprawdzony · Claude</span>`;return`<span class="badge ${reviewed(i)?'':'warn'}">${reviewed(i)?'Klucz sprawdzony · CDC':'Bez bieżącej weryfikacji'}</span>`}

/* ---- mieszanie: kolejność pytań i odpowiedzi ---- */
function shuffleOn(){return read('infectio-shuffle',true)!==false}
function optionOrder(s,i){const o=parseOptions(i);if(!shuffleOn())return o;s.perm=s.perm||{};if(!s.perm[s.index])s.perm[s.index]=shuffle(o.map(x=>x.letter));return s.perm[s.index].map(l=>o.find(x=>x.letter===l)).filter(Boolean)}
document.addEventListener('change',e=>{if(e.target.id!=='shuffle-toggle')return;save('infectio-shuffle',e.target.checked);toast(e.target.checked?'Mieszanie włączone: pytania i odpowiedzi w losowej kolejności.':'Mieszanie wyłączone: kolejność jak w bazie.')});
